module SplitMultiplier_16(
  input        clock,
               reset,
  input  [7:0] io_a,
  output [7:0] io_out_fixed,
  input        io_valid_in,
  output       io_valid_out
);

  reg [17:0] partials_0;
  reg [17:0] acc;
  reg        valid;
  reg        io_valid_out_REG;
  always @(posedge clock) begin
    if (reset) begin
      partials_0 <= 18'h0;
      acc <= 18'h0;
      valid <= 1'h0;
    end
    else begin
      partials_0 <= {{10{io_a[7]}}, io_a} * 18'h5B;
      acc <= partials_0;
      valid <= io_valid_in;
    end
    io_valid_out_REG <= valid;
  end // always @(posedge)
  assign io_out_fixed = acc[14:7];
  assign io_valid_out = io_valid_out_REG;
endmodule

module ControlledTGate(
  input        clock,
               reset,
  input  [7:0] io_in_QSV_0_0,
               io_in_QSV_0_1,
               io_in_QSV_1_0,
               io_in_QSV_1_1,
               io_in_QSV_2_0,
               io_in_QSV_2_1,
               io_in_QSV_3_0,
               io_in_QSV_3_1,
  input        io_in_valid,
  output [7:0] io_out_QSV_0_0,
               io_out_QSV_0_1,
               io_out_QSV_1_0,
               io_out_QSV_1_1,
               io_out_QSV_2_0,
               io_out_QSV_2_1,
               io_out_QSV_3_0,
               io_out_QSV_3_1,
  output       io_out_valid
);

  wire       _multiplierImag_io_valid_out;
  wire       _multiplierReal_io_valid_out;
  reg  [7:0] regout0_0;
  reg  [7:0] regout0_1;
  reg  [7:0] regout1_0;
  reg  [7:0] regout1_1;
  reg  [7:0] regout2_0;
  reg  [7:0] regout2_1;
  always @(posedge clock) begin
    if (reset) begin
      regout0_0 <= 8'h0;
      regout0_1 <= 8'h0;
      regout1_0 <= 8'h0;
      regout1_1 <= 8'h0;
      regout2_0 <= 8'h0;
      regout2_1 <= 8'h0;
    end
    else begin
      regout0_0 <= io_in_QSV_0_0;
      regout0_1 <= io_in_QSV_0_1;
      regout1_0 <= io_in_QSV_1_0;
      regout1_1 <= io_in_QSV_1_1;
      regout2_0 <= io_in_QSV_2_0;
      regout2_1 <= io_in_QSV_2_1;
    end
  end // always @(posedge)
  SplitMultiplier_16 multiplierReal (
    .clock        (clock),
    .reset        (reset),
    .io_a         (io_in_QSV_3_0),
    .io_out_fixed (io_out_QSV_3_0),
    .io_valid_in  (io_in_valid),
    .io_valid_out (_multiplierReal_io_valid_out)
  );
  SplitMultiplier_16 multiplierImag (
    .clock        (clock),
    .reset        (reset),
    .io_a         (io_in_QSV_3_1),
    .io_out_fixed (io_out_QSV_3_1),
    .io_valid_in  (io_in_valid),
    .io_valid_out (_multiplierImag_io_valid_out)
  );
  assign io_out_QSV_0_0 = regout0_0;
  assign io_out_QSV_0_1 = regout0_1;
  assign io_out_QSV_1_0 = regout1_0;
  assign io_out_QSV_1_1 = regout1_1;
  assign io_out_QSV_2_0 = regout2_0;
  assign io_out_QSV_2_1 = regout2_1;
  assign io_out_valid = _multiplierReal_io_valid_out & _multiplierImag_io_valid_out;
endmodule

