  reg [7:0] reg_0_0;
  reg [7:0] reg_0_1;
  reg [7:0] reg_1_0;
  reg [7:0] reg_1_1;
  reg [7:0] reg_2_0;
  reg [7:0] reg_2_1;
  reg [7:0] reg_3_0;
  reg [7:0] reg_3_1;
  reg       io_out_valid_REG;
  always @(posedge clock) begin
    if (reset) begin
      reg_0_0 <= 8'h0;
      reg_0_1 <= 8'h0;
      reg_1_0 <= 8'h0;
      reg_1_1 <= 8'h0;
      reg_2_0 <= 8'h0;
      reg_2_1 <= 8'h0;
      reg_3_0 <= 8'h0;
      reg_3_1 <= 8'h0;
      io_out_valid_REG <= 1'h0;
    end
    else begin
      reg_0_0 <= io_in_QSV_0_0;
      reg_0_1 <= io_in_QSV_0_1;
      reg_1_0 <= io_in_QSV_2_0;
      reg_1_1 <= io_in_QSV_2_1;
      reg_2_0 <= io_in_QSV_1_0;
      reg_2_1 <= io_in_QSV_1_1;
      reg_3_0 <= io_in_QSV_3_0;
      reg_3_1 <= io_in_QSV_3_1;
      io_out_valid_REG <= io_in_valid;
    end
  end // always @(posedge)
  assign io_out_QSV_0_0 = reg_0_0;
  assign io_out_QSV_0_1 = reg_0_1;
  assign io_out_QSV_1_0 = reg_1_0;
  assign io_out_QSV_1_1 = reg_1_1;
  assign io_out_QSV_2_0 = reg_2_0;
  assign io_out_QSV_2_1 = reg_2_1;
  assign io_out_QSV_3_0 = reg_3_0;
  assign io_out_QSV_3_1 = reg_3_1;
  assign io_out_valid = io_out_valid_REG;
endmodule

module SWGate8bit(
