               io_out_QSV_2_0,
               io_out_QSV_2_1,
               io_out_QSV_3_0,
               io_out_QSV_3_1,
  output       io_out_valid
);

  SwapGate gate (
    .clock          (clock),
    .reset          (reset),
    .io_in_QSV_0_0  (io_in_QSV_0_0),
    .io_in_QSV_0_1  (io_in_QSV_0_1),
